#!/bin/sh
# Caligrafy Quill QA suite.
#
#   qa/run.sh          build the isolated stack, run all tests, tear everything down
#   qa/run.sh --keep   leave the stack and the generated files in place (debugging)
#
# Requires Docker, PHP >= 8.1 with curl on the host, Composer dependencies installed (vendor/) and Node.js.
# The stack uses its own compose project (quillqa) and ports (QA_WEB_PORT=8090, QA_DB_PORT=3316).
# It refuses to run if application/ or .env exist and were not created by a previous QA run.

set -u
cd "$(dirname "$0")/.."
ROOT=$(pwd)
COMPOSE="docker compose -f qa/docker-compose.yml"
KEEP=0
[ "${1:-}" = "--keep" ] && KEEP=1
export QA_WEB_PORT=${QA_WEB_PORT:-8090}
export QA_BASE="http://localhost:$QA_WEB_PORT"

fail() { echo "qa: $*" >&2; exit 2; }

# --- guard the developer's own files ------------------------------------------------
[ -d vendor ] || fail "run 'composer install' first"
if [ -d application ] && [ ! -f application/.qa-generated ]; then fail "application/ exists and is not QA-generated; run the suite on a clean checkout"; fi
if [ -f .env ] && ! grep -q '^# QA-GENERATED' .env; then fail ".env exists and is not QA-generated; move it aside first"; fi

cleanup() {
    if [ "$KEEP" = 1 ]; then echo "qa: --keep: stack and generated files left in place"; return; fi
    $COMPOSE down -v >/dev/null 2>&1
    rm -rf application public/qaapp public/qabot public/qaspa .env qa/tmp
    for f in public/uploads/*; do
        [ -e "$f" ] || continue
        echo "$UPLOADS_BEFORE" | grep -qxF "$f" || rm -f "$f"
    done
}
UPLOADS_BEFORE=$(ls -d public/uploads/* 2>/dev/null)
trap cleanup EXIT

# --- .env -----------------------------------------------------------------------------
KEYS=$(php caligrafer.php generatekeys 2>/dev/null)
APP_KEY=$(echo "$KEYS" | sed -n 's/^ *APP_KEY=//p')
API_KEY=$(echo "$KEYS" | sed -n 's/^ *API_KEY=//p')
[ -n "$APP_KEY" ] || fail "could not generate keys"
{
    echo "# QA-GENERATED by qa/run.sh - safe to delete"
    echo "APP_KEY=$APP_KEY"
    echo "API_KEY=$API_KEY"
    echo "APP_ROOT="
    echo "WATSON_URL=http://127.0.0.1:8769/instances/qa-instance"
    sed -e 's/^DB_ACTIVATE=.*/DB_ACTIVATE=true/' -e 's/^DB_HOST=.*/DB_HOST=mysql/' \
        -e 's/^DB_DATABASE=.*/DB_DATABASE=quillqa/' -e '/^WATSON_URL=/d' framework/settings/.env.example
} > .env

# --- application/ and client apps -------------------------------------------------------
rm -rf application public/qaapp public/qabot
cp -r framework/settings/application ./application
touch application/.qa-generated
cp -r qa/fixtures/application/. application/
php -r '
$f = "application/config/routing/web.php";
$s = file_get_contents($f);
$s = preg_replace("#^(\s*)// (Auth::authentication|Route::)#m", "$1$2", $s);
$qa = "    Route::get(\"/qa/books/{id}\", \"QaController@books\");\n    Route::post(\"/qa/upload\", \"QaController@upload\");\n"
    . "    Route::get(\"/books\", \"BookController@readAll\");\n    Route::post(\"/books\", \"BookController@create\");\n"
    . "    Route::put(\"/books/{id}\", \"BookController@update\");\n    Route::delete(\"/books/{id}\", \"BookController@remove\");\n"
    . "    Route::get(\"/books/{id}/publisher\", \"BookController@publisher\");\n";
$s = str_replace("    Route::run();", $qa . "    Route::run();", $s);
file_put_contents($f, $s);
'
cp -r framework/plugins/app public/qaapp
printf '<?php echo "QA-SECOND-PAGE";\n' > public/qaapp/second.php
cp qa/fixtures/docs/components.php public/qaapp/components.php
cp qa/fixtures/docs/components.js public/qaapp/scripts/components.js
cp -r framework/plugins/bot public/qabot

# --- stack --------------------------------------------------------------------------------
echo "qa: starting the stack (web :$QA_WEB_PORT, mysql :${QA_DB_PORT:-3316})"
$COMPOSE up -d --build --wait >/dev/null 2>&1 || { $COMPOSE up -d --build; fail "docker compose up failed"; }
i=0
until [ "$(curl -s -o /dev/null -w '%{http_code}' "$QA_BASE/helloworld")" = "200" ]; do
    i=$((i + 1)); [ $i -gt 60 ] && fail "web container did not answer on $QA_BASE"; sleep 1
done
$COMPOSE exec -T mysql mysql -uroot -proot quillqa < framework/settings/application/models/Auth/create_db.sql 2>/dev/null \
    || fail "could not create the users table"
$COMPOSE exec -T mysql mysql -uroot -proot quillqa < qa/fixtures/books.sql 2>/dev/null || fail "could not create the books tables"
# Watson mock inside the web container, used by WatsonController in the HTTP tests
$COMPOSE exec -d web php -S 127.0.0.1:8769 qa/fixtures/watson_mock.php

STATUS=0

echo
echo "== Database scripts"
$COMPOSE exec -T mysql mysql -uroot -proot quillqa -e "INSERT INTO users (username, passcode) VALUES ('keepme', 'x')" 2>/dev/null
$COMPOSE exec -T mysql mysql -uroot -proot quillqa < framework/settings/application/models/Auth/create_db.sql 2>/dev/null
KEPT=$($COMPOSE exec -T mysql mysql -uroot -proot quillqa -N -e "SELECT COUNT(*) FROM users WHERE username = 'keepme'" 2>/dev/null)
if [ "$KEPT" = "1" ]; then echo "  PASS Auth create_db.sql can be re-run without deleting users"; else echo "  FAIL Auth create_db.sql deleted the users table"; STATUS=1; fi
$COMPOSE exec -T mysql mysql -uroot -proot quillqa -e "DELETE FROM users" 2>/dev/null

echo
echo "== Framework tests (inside the web container)"
$COMPOSE exec -T web php qa/tests/cli_tests.php || STATUS=1

echo
echo "== HTTP tests"
php qa/tests/http_tests.php || STATUS=1

echo
echo "== Hosts that only allow 'AllowOverride FileInfo' (mod_rewrite, no AuthConfig/Options)"
$COMPOSE exec -T web sh -c "sed -i 's/AllowOverride All/AllowOverride FileInfo/' /etc/apache2/conf-enabled/docker-php.conf && apachectl -k graceful" >/dev/null 2>&1
sleep 2
printf '<?php echo "EXEC" . "UTED";' > public/uploads/qa_probe.php
for check in "/helloworld 200" "/ 200" "/public/css/styles.css 200" "/.env 403" "/composer.json 403" "/Composer.json 403" "/public/uploads/qa_probe.php 403" "/public/uploads/qa_probe.PHP 403"; do
    set -- $check
    CODE=$(curl -s -o /dev/null -w '%{http_code}' "$QA_BASE$1")
    if [ "$CODE" = "$2" ]; then echo "  PASS $1 -> $CODE"; else echo "  FAIL $1 -> $CODE (expected $2)"; STATUS=1; fi
done
rm -f public/uploads/qa_probe.php
$COMPOSE exec -T web sh -c "sed -i 's/AllowOverride FileInfo/AllowOverride All/' /etc/apache2/conf-enabled/docker-php.conf && apachectl -k graceful" >/dev/null 2>&1
sleep 2

echo
echo "== Tooling tests"
sh qa/tests/tooling_tests.sh || STATUS=1

exit $STATUS
